"use client";

import { cva } from "class-variance-authority";
import * as React from "react";
import { cn } from "../../lib/utils.js";

type StepStatus = "complete" | "current" | "upcoming" | "error";

interface StepperStep {
	/** Stable unique id used as the React key. */
	id: string;
	/** Step name shown next to the indicator. */
	label: string;
	/** Optional secondary text under the label. */
	description?: string;
	/** Disable the step (only applies when onStepClick is provided). */
	disabled?: boolean;
	/**
	 * Override the index-derived status. Use `"error"` to mark a failed step
	 * (e.g. validation failure in a form wizard); `"complete"` / `"current"` /
	 * `"upcoming"` are derived from `current` by default.
	 */
	status?: StepStatus;
}

const stepperRoot = cva(
	"flex w-full gap-[var(--gap-md,1rem)] list-none p-0 m-0",
	{
		variants: {
			orientation: {
				horizontal: "flex-row items-start",
				vertical: "flex-col items-stretch",
			},
		},
		defaultVariants: { orientation: "horizontal" },
	},
);

/*
 * Horizontal: each step sizes to its content; the connector (`flex-1`) fills
 * the gap between steps. Going `flex-1` on the step item itself would shrink
 * labels to the point of `text-overflow: ellipsis` ("Account" → "A...").
 * Vertical: items take the full width so multi-line descriptions wrap
 * naturally below the indicator.
 */
const stepItem = cva("flex gap-[var(--space-3,0.75rem)]", {
	variants: {
		orientation: {
			horizontal: "flex-row items-center",
			vertical: "flex-row items-start w-full",
		},
	},
	defaultVariants: { orientation: "horizontal" },
});

const stepIndicator = cva(
	"inline-flex shrink-0 items-center justify-center rounded-full border-2 font-medium transition-all duration-[var(--duration-normal,200ms)] ease-out",
	{
		variants: {
			size: {
				sm: "h-7 w-7 text-xs",
				default: "h-[var(--control-height-sm,2.25rem)] w-[var(--control-height-sm,2.25rem)] text-sm",
				lg: "h-[var(--control-height-md,2.75rem)] w-[var(--control-height-md,2.75rem)] text-base",
			},
			status: {
				complete: "bg-primary border-primary text-primary-foreground",
				current: "bg-background border-primary text-primary",
				upcoming: "bg-background border-input text-muted-foreground",
				error:
					"bg-destructive border-destructive text-destructive-foreground",
			},
		},
		defaultVariants: { size: "default", status: "upcoming" },
	},
);

const stepConnector = cva("bg-input transition-all duration-[var(--duration-normal,200ms)] ease-out", {
	variants: {
		orientation: {
			horizontal: "h-px flex-1 min-w-[var(--space-6,1.5rem)] mx-[var(--space-2,0.5rem)]",
			vertical: "w-px self-stretch ml-[1.0625rem] my-[var(--space-1,0.25rem)] min-h-[var(--space-6,1.5rem)]",
		},
		complete: {
			true: "bg-primary",
			false: "",
		},
	},
	defaultVariants: { orientation: "horizontal", complete: false },
});

interface StepperProps
	extends Omit<
		React.HTMLAttributes<HTMLOListElement>,
		"aria-label" | "onClick"
	> {
	/** Ordered list of steps. */
	steps: StepperStep[];
	/** Index of the current step (controlled). */
	current: number;
	/** Layout direction. */
	orientation?: "horizontal" | "vertical";
	/** Indicator size. */
	size?: "sm" | "default" | "lg";
	/** When provided, each step is rendered as a clickable button. */
	onStepClick?: (index: number) => void;
	/** Required accessible name for the ordered list. */
	"aria-label": string;
}

/** Map a step index against the current pointer to a `StepStatus`. */
function deriveStatus(index: number, current: number): StepStatus {
	if (index < current) return "complete";
	if (index === current) return "current";
	return "upcoming";
}

/** Checkmark glyph rendered inside the indicator for completed steps. */
function StepCheck() {
	return (
		<svg
			xmlns="http://www.w3.org/2000/svg"
			viewBox="0 0 24 24"
			fill="none"
			stroke="currentColor"
			strokeWidth="3"
			strokeLinecap="round"
			strokeLinejoin="round"
			className="h-4 w-4"
			aria-hidden="true"
		>
			<polyline points="20 6 9 17 4 12" />
		</svg>
	);
}

/** Cross glyph rendered inside the indicator for steps with status="error". */
function StepError() {
	return (
		<svg
			xmlns="http://www.w3.org/2000/svg"
			viewBox="0 0 24 24"
			fill="none"
			stroke="currentColor"
			strokeWidth="3"
			strokeLinecap="round"
			strokeLinejoin="round"
			className="h-4 w-4"
			aria-hidden="true"
		>
			<line x1="6" y1="6" x2="18" y2="18" />
			<line x1="18" y1="6" x2="6" y2="18" />
		</svg>
	);
}

interface StepIndicatorProps {
	index: number;
	status: StepStatus;
	size: "sm" | "default" | "lg";
}

/** Circular indicator that flips between number, check, and cross by `status`. */
function StepIndicator({ index, status, size }: StepIndicatorProps) {
	return (
		<span
			className={stepIndicator({ size, status })}
			aria-invalid={status === "error" ? true : undefined}
		>
			{status === "complete" ? (
				<StepCheck />
			) : status === "error" ? (
				<StepError />
			) : (
				index + 1
			)}
		</span>
	);
}

/**
 * Linear progress indicator for multi-step flows (form wizards, onboarding,
 * checkout). Pure semantic HTML — `<ol>` of `<li>` with `aria-current="step"`
 * on the current item; per-step `status` overrides allow marking "error".
 *
 * Pass `onStepClick` to make completed/non-disabled steps interactive.
 * @returns An accessible ordered step list.
 */
function Stepper({
	steps,
	current,
	orientation = "horizontal",
	size = "default",
	onStepClick,
	"aria-label": ariaLabel,
	className,
	...rest
}: StepperProps) {
	const interactive = typeof onStepClick === "function";
	return (
		<ol
			aria-label={ariaLabel}
			className={cn(stepperRoot({ orientation }), className)}
			{...rest}
		>
			{steps.map((step, index) => {
				const status = step.status ?? deriveStatus(index, current);
				const isCurrent = status === "current";
				const isLast = index === steps.length - 1;
				const labelNode = (
					<span className="flex flex-col gap-[var(--space-1,0.25rem)]">
						<span
							className={cn(
								"text-sm font-medium whitespace-nowrap",
								isCurrent && "text-foreground",
								status === "complete" && "text-foreground",
								status === "upcoming" && "text-muted-foreground",
								status === "error" && "text-destructive",
							)}
						>
							{status === "complete" && (
								<span className="sr-only">Completed: </span>
							)}
							{status === "error" && (
								<span className="sr-only">Error: </span>
							)}
							{step.label}
						</span>
						{step.description ? (
							<span className="text-xs text-muted-foreground">
								{step.description}
							</span>
						) : null}
					</span>
				);

				const innerContent = (
					<>
						<StepIndicator index={index} status={status} size={size} />
						{labelNode}
					</>
				);

				return (
					/*
					 * `aria-current="step"` lives on the <li> itself so screen
					 * readers announce it as part of the listitem's intro
					 * (per WAI guidance for "step" lists), not buried on an
					 * interior span/button.
					 */
					<li
						key={step.id}
						aria-current={isCurrent ? "step" : undefined}
						className={cn(
							stepItem({ orientation }),
							/*
							 * Grow only when there's a connector after this step.
							 * The connector inside takes the extra space via
							 * `flex-1` so the line spans to the next step.
							 */
							!isLast && orientation === "horizontal" && "flex-1",
							!isLast && orientation === "vertical" && "flex-col",
						)}
					>
						{interactive ? (
							<button
								type="button"
								disabled={step.disabled}
								onClick={() => onStepClick?.(index)}
								className={cn(
									"flex items-center gap-[var(--space-3,0.75rem)] text-left rounded-md transition-all duration-[var(--duration-normal,200ms)] ease-out",
									"focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
									"disabled:opacity-50 disabled:pointer-events-none",
								)}
							>
								{innerContent}
							</button>
						) : (
							<span className="flex items-center gap-[var(--space-3,0.75rem)]">
								{innerContent}
							</span>
						)}
						{!isLast ? (
							/*
							 * Connector "complete" iff THIS step is finished. An
							 * explicit "error" status on the current step never
							 * fills the gap to the next step — the user hasn't
							 * cleared this milestone.
							 */
							<span
								aria-hidden="true"
								className={stepConnector({
									orientation,
									complete: index < current && step.status !== "error",
								})}
							/>
						) : null}
					</li>
				);
			})}
		</ol>
	);
}
Stepper.displayName = "Stepper";

export { Stepper };
export type { StepperProps, StepperStep, StepStatus };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex Core: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const SAFE_URL_SCHEMES = ["http:", "https:", "mailto:"] as const;

/**
 * Allowlist a URL for use as an `<a href>` against untrusted input.
 *
 * Returns the raw string when it's `http(s):` / `mailto:` / a relative
 * URL (no scheme); returns `undefined` otherwise. Defends against
 * `javascript:` / `data:` / `vbscript:` injection from streamed model
 * output or third-party JSON payloads that flow into citation chips.
 *
 * Inside a Markdown render path, `rehype-sanitize` already strips
 * `javascript:` from inline-link hrefs — but it does NOT introspect
 * JSON nested inside attribute values (e.g. `<sources data='[…]'/>`),
 * so the components that consume that data must guard themselves.
 *
 * @param raw - The candidate URL, or `undefined` when none was supplied.
 * @returns The URL when safe to render, otherwise `undefined`.
 */
export function safeUrl(raw: string | undefined): string | undefined {
	if (raw === undefined || raw === "") return undefined;
	// Relative URLs have no scheme — `new URL(relative)` throws without a base,
	// so a thrown URL means either malformed input OR a relative path. Treat
	// "throws + does not contain a colon" as a relative path (safe).
	let parsed: URL;
	try {
		parsed = new URL(raw);
	} catch {
		return raw.includes(":") ? undefined : raw;
	}
	return SAFE_URL_SCHEMES.some((scheme) => scheme === parsed.protocol) ? raw : undefined;
}

